insert into hazards (id, route_id, lat, lng, type, description, severity) select gen_random_uuid(), id, 51.576442, 0.022472, 'junction', 'Tight junction — position early and check both mirrors before turning.', 'medium' from routes where name = 'Route 8 · The Avenue and Kingfisher Avenue' and centre_id = (select id from test_centres where name = 'Wanstead');
insert into hazards (id, route_id, lat, lng, type, description, severity) select gen_random_uuid(), id, 51.574502, 0.024956, 'roundabout', 'Busy roundabout — mirror-signal-position on approach, watch lane discipline on exit.', 'low' from routes where name = 'Route 8 · The Avenue and Kingfisher Avenue' and centre_id = (select id from test_centres where name = 'Wanstead');
