insert into hazards (id, route_id, lat, lng, type, description, severity) select gen_random_uuid(), id, 51.640671, 0.068349, 'junction', 'Tight junction — position early and check both mirrors before turning.', 'medium' from routes where name = 'Route 2 · High Road and Abridge Road' and centre_id = (select id from test_centres where name = 'Loughton');
insert into hazards (id, route_id, lat, lng, type, description, severity) select gen_random_uuid(), id, 51.634996, 0.086943, 'roundabout', 'Busy roundabout — mirror-signal-position on approach, watch lane discipline on exit.', 'low' from routes where name = 'Route 2 · High Road and Abridge Road' and centre_id = (select id from test_centres where name = 'Loughton');
