insert into hazards (id, route_id, lat, lng, type, description, severity) select gen_random_uuid(), id, 54.982728, -1.60446, 'junction', 'Tight junction — position early and check both mirrors before turning.', 'high' from routes where name = 'Route 10 · Two Ball Lonnen and Sandyford Road' and centre_id = (select id from test_centres where name = 'Newcastle');
insert into hazards (id, route_id, lat, lng, type, description, severity) select gen_random_uuid(), id, 55.002946, -1.620139, 'roundabout', 'Busy roundabout — mirror-signal-position on approach, watch lane discipline on exit.', 'high' from routes where name = 'Route 10 · Two Ball Lonnen and Sandyford Road' and centre_id = (select id from test_centres where name = 'Newcastle');
insert into hazards (id, route_id, lat, lng, type, description, severity) select gen_random_uuid(), id, 55.002241, -1.622686, 'zebra', 'Pedestrian crossing — scan pavements early and be ready to stop smoothly.', 'medium' from routes where name = 'Route 10 · Two Ball Lonnen and Sandyford Road' and centre_id = (select id from test_centres where name = 'Newcastle');
insert into hazards (id, route_id, lat, lng, type, description, severity) select gen_random_uuid(), id, 55.006159, -1.625991, 'narrow', 'Narrow section with parked cars — hold back and give way where the obstruction is on your side.', 'low' from routes where name = 'Route 10 · Two Ball Lonnen and Sandyford Road' and centre_id = (select id from test_centres where name = 'Newcastle');
insert into show_me_tell_me (id, category, topic, question, answer, is_show_me, choices) values (gen_random_uuid(), 'safety', 'Tyre tread and condition', 'Show me how you''d check that the tyres on this car have sufficient tread depth and are in a safe condition to drive.', 'I''d check the tread depth is at least 1.6mm across the central three-quarters of the tyre''s width, look for cuts or bulges, and check the pressures with a gauge if one is available.', true, '[{"text":"Check at least 1mm of tread across the full width, and that all four tyres are the same brand","correct":false},{"text":"Check at least 1.6mm across the central three-quarters, plus cuts and bulges","correct":true},{"text":"Check at least 2.5mm of tread at the outer edges, measuring while the tyres are still warm","correct":false},{"text":"Press each tyre by hand for firmness — there is no legal minimum tread depth","correct":false}]'::jsonb);
insert into show_me_tell_me (id, category, topic, question, answer, is_show_me, choices) values (gen_random_uuid(), 'inside_car', 'The horn', 'Show me how you''d check that the horn is working (off road only).', 'I''d press the horn control, usually found on the steering wheel, to sound it briefly.', true, '[{"text":"Press the horn control on the steering wheel and sound it briefly","correct":true},{"text":"Hold the horn down for several seconds so the tone can be judged properly","correct":false},{"text":"Switch the ignition off first, then press the horn control on the steering wheel","correct":false},{"text":"Pull the indicator stalk towards me, which sounds the horn on most cars","correct":false}]'::jsonb);
insert into show_me_tell_me (id, category, topic, question, answer, is_show_me, choices) values (gen_random_uuid(), 'inside_car', 'Demisting the windows', 'Show me how you''d set the demister controls to clear all the windows effectively.', 'I''d switch on the fan and heater, select the windscreen setting, choose a warm airflow, and switch on the heated rear window and air conditioning if fitted.', true, '[{"text":"Set the fan to recirculate with a cool airflow, aimed at the side windows","correct":false},{"text":"Fan and heater on, windscreen setting selected, warm airflow, plus the heated rear window","correct":true},{"text":"Fan on full with a cold airflow and both front windows open, which clears it fastest","correct":false},{"text":"Wait for the engine to warm through, then direct the fan at the footwells","correct":false}]'::jsonb);
insert into show_me_tell_me (id, category, topic, question, answer, is_show_me, choices) values (gen_random_uuid(), 'inside_car', 'Main beam', 'Show me how you''d switch your headlights from dipped to main beam and explain how you''d know the main beam is on.', 'I''d move the indicator stalk forward, or press the light switch, to select main beam, and a blue warning light on the dashboard confirms it''s on.', true, '[{"text":"Push the stalk forward for main beam — a green warning light on the dashboard confirms it","correct":false},{"text":"Pull the stalk towards me and hold it — main beam stays on only while it is held","correct":false},{"text":"Push the stalk forward for main beam — a blue warning light on the dashboard confirms it","correct":true},{"text":"Turn the light switch to its third position — an amber warning light confirms it","correct":false}]'::jsonb);
insert into show_me_tell_me (id, category, topic, question, answer, is_show_me, choices) values (gen_random_uuid(), 'inside_car', 'Brake test on the move', 'Show me how you''d check the footbrake is working effectively as you move away, without the car pulling to either side.', 'As I move off, I''d press the brake pedal firmly and check the car stops smoothly and promptly, travelling in a straight line without pulling to one side.', true, '[{"text":"Press the brake firmly just after moving off and check it slows promptly and straight","correct":true},{"text":"Brake hard from about 30mph and check the anti-lock system engages properly","correct":false},{"text":"Press the brake while stationary and check the pedal does not sink to the floor","correct":false},{"text":"Coast in neutral and check the car slows evenly without touching the brake","correct":false}]'::jsonb);
insert into show_me_tell_me (id, category, topic, question, answer, is_show_me, choices) values (gen_random_uuid(), 'inside_car', 'Washer and wipers', 'Show me how you''d clean the windscreen using the windscreen washer and wiper.', 'I''d operate the washer stalk or button so washer fluid sprays the screen, then let the wipers clear it, repeating until the screen is clean.', true, '[{"text":"Run the wipers on the dry screen first, then add fluid once the dust is swept off","correct":false},{"text":"Operate the washer so fluid sprays the screen, let the wipers clear it, and repeat","correct":true},{"text":"Spray the washers with the ignition off, so no fluid is wasted while the engine runs","correct":false},{"text":"Use the rear washer control, which operates both screens together on most cars","correct":false}]'::jsonb);
insert into show_me_tell_me (id, category, topic, question, answer, is_show_me, choices) values (gen_random_uuid(), 'inside_car', 'Rear fog lights', 'Show me how you''d switch on your rear fog light(s) and explain when you''d use it/them.', 'I''d pull out or press the switch marked with a light symbol crossed by three horizontal lines, and I''d only use it when visibility drops below 100 metres.', true, '[{"text":"The switch marked with a lamp crossed by three sloping lines, used in heavy rain","correct":false},{"text":"The switch marked with a lamp and a wavy line, used in any fog however light","correct":false},{"text":"The lamp crossed by three level lines — used below 100 metres visibility","correct":true},{"text":"The main beam stalk pushed forward, used at night on unlit roads","correct":false}]'::jsonb);
insert into show_me_tell_me (id, category, topic, question, answer, is_show_me, choices) values (gen_random_uuid(), 'safety', 'Brakes before a journey', 'Tell me how you''d check that the brakes are working before starting a journey.', 'I''d press the brake pedal before moving off and check it feels firm, with no excessive travel and no sponginess.', false, '[{"text":"Pull away and brake hard from 30mph to check it stops within the legal distance","correct":false},{"text":"Press the brake pedal before moving off and check it feels firm, not spongy","correct":true},{"text":"Check the brake fluid reservoir is filled to the top of its neck","correct":false},{"text":"Listen for the brakes squealing on the first few stops, the usual sign of a fault","correct":false}]'::jsonb);
insert into show_me_tell_me (id, category, topic, question, answer, is_show_me, choices) values (gen_random_uuid(), 'safety', 'Tyre pressures', 'Tell me where you''d find the recommended tyre pressures for this car and how you''d check them.', 'The recommended pressures are usually shown in the handbook, on a sticker inside the driver''s door sill, or on the fuel filler flap, and I''d check them with a pressure gauge when the tyres are cold.', false, '[{"text":"On the sidewall of each tyre, checked with a gauge once the tyres have warmed up","correct":false},{"text":"In the handbook, the door sill or the filler flap — checked with a gauge, tyres cold","correct":true},{"text":"Under the bonnet by the oil filler cap, checked by pressing each tyre firmly by hand","correct":false},{"text":"On a plate beside the engine number, checked at a garage once a year at service time","correct":false}]'::jsonb);
insert into show_me_tell_me (id, category, topic, question, answer, is_show_me, choices) values (gen_random_uuid(), 'safety', 'Head restraint', 'Tell me how you''d check the head restraint is correctly adjusted so it provides the best protection in the event of a crash.', 'The head restraint should be adjusted so the rigid part is level with the top of my head, and as close to the back of my head as is comfortable.', false, '[{"text":"The rigid part level with the top of my shoulders, a hand''s width behind my head","correct":false},{"text":"Set as low as it will go, so it does not block my view through the rear window","correct":false},{"text":"The rigid part level with the top of my head, and as close behind it as is comfortable","correct":true},{"text":"The soft part against the back of my neck, with the rigid part above the roof line","correct":false}]'::jsonb);
insert into show_me_tell_me (id, category, topic, question, answer, is_show_me, choices) values (gen_random_uuid(), 'safety', 'Tyre tread, the legal minimum', 'Tell me how you''d check the tyres have sufficient tread depth and that their general condition is safe to use.', 'The legal minimum tread depth is 1.6mm across the central three-quarters of the tyre''s width around its entire circumference, and I''d also check for cuts and bulges.', false, '[{"text":"1.6mm across the central three-quarters, right round the tyre, plus cuts and bulges","correct":true},{"text":"1.6mm anywhere on the tyre, so long as one part of the tread still meets the depth","correct":false},{"text":"1mm across the central three-quarters, right round the tyre, plus uneven wear","correct":false},{"text":"3mm across the full width, which is the depth a tyre must be replaced at","correct":false}]'::jsonb);
insert into show_me_tell_me (id, category, topic, question, answer, is_show_me, choices) values (gen_random_uuid(), 'safety', 'Direction indicators', 'Tell me how you''d check the direction indicators are working.', 'I''d switch on the hazard warning lights, or each indicator in turn, and walk round the vehicle to check all the lights are flashing, or ask someone to confirm while I operate them.', false, '[{"text":"Switch on the hazards, or each indicator in turn, and walk round checking every lamp","correct":true},{"text":"Switch on the hazards and check the dashboard tell-tale flashes, covering all four","correct":false},{"text":"Operate each indicator with the ignition off and listen for the relay ticking","correct":false},{"text":"Switch on the sidelights first, then the indicators, so the difference can be seen","correct":false}]'::jsonb);
insert into show_me_tell_me (id, category, topic, question, answer, is_show_me, choices) values (gen_random_uuid(), 'safety', 'Brake lights', 'Tell me how you''d check the brake lights are working on this car.', 'With the ignition on, I''d operate the footbrake and use a reflection in a window or garage door, or ask someone to check the lights come on.', false, '[{"text":"With the ignition off, press the footbrake and check the lights in a reflection","correct":false},{"text":"Pull the handbrake fully on and check the brake lights come on at the back","correct":false},{"text":"With the ignition on, press the footbrake and use a reflection, or ask someone","correct":true},{"text":"Press the footbrake and check the red warning light on the dashboard comes on","correct":false}]'::jsonb);
insert into show_me_tell_me (id, category, topic, question, answer, is_show_me, choices) values (gen_random_uuid(), 'inside_car', 'Headlights and sidelights', 'Tell me how you''d check your headlights and sidelights are working, without getting out of the car.', 'I''d switch them on and check the dashboard light confirms they''re lit, and I could check their reflection in a window or ask someone to confirm they''re working.', false, '[{"text":"Switch them on and walk round the car with the engine running to see each one lit","correct":false},{"text":"Switch them on, check the dashboard tell-tale, and use a reflection or ask someone","correct":true},{"text":"Switch them on and check the fuse box under the bonnet for a blown fuse","correct":false},{"text":"Flash them twice and listen for the relay clicking behind the dashboard","correct":false}]'::jsonb);
insert into show_me_tell_me (id, category, topic, question, answer, is_show_me, choices) values (gen_random_uuid(), 'inside_car', 'Anti-lock brakes', 'Tell me how you''d know if there was a problem with your anti-lock braking system.', 'A warning light on the instrument panel would illuminate and stay lit if there''s a fault with the ABS.', false, '[{"text":"The brake pedal would feel spongy and travel much further than usual","correct":false},{"text":"A warning light on the instrument panel would come on and stay lit","correct":true},{"text":"The car would pull noticeably to one side under firm braking","correct":false},{"text":"The ABS pump would run noisily whenever the ignition is switched on","correct":false}]'::jsonb);
insert into show_me_tell_me (id, category, topic, question, answer, is_show_me, choices) values (gen_random_uuid(), 'inside_car', 'Power-assisted steering', 'Tell me how you''d check the power-assisted steering is working before starting a journey.', 'If the steering feels unusually heavy, or there''s no resistance after gently turning the wheel and pulling away, it may indicate a fault, and a dashboard warning light would also alert me.', false, '[{"text":"Turn the wheel fully lock to lock while parked and listen for the pump straining","correct":false},{"text":"Check the wheel has no more than two inches of free play before the wheels move","correct":false},{"text":"Gently turn the wheel as I pull away — steering that feels heavy suggests a fault","correct":true},{"text":"Check the power steering fluid sits above the maximum mark on its reservoir","correct":false}]'::jsonb);
insert into show_me_tell_me (id, category, topic, question, answer, is_show_me, choices) values (gen_random_uuid(), 'inside_car', 'When to use fog lights', 'Tell me when you''d use front or rear fog lights and how you''d know they''re switched on.', 'I''d use them only when visibility is seriously reduced to less than 100 metres, and a warning light on the dashboard shows when they''re switched on.', false, '[{"text":"Whenever it is raining hard enough for the wipers to be running continuously","correct":false},{"text":"Only below 100 metres visibility — a dashboard warning light shows they are on","correct":true},{"text":"At any time after dark on an unlit road, in place of main beam","correct":false},{"text":"Only below 100 metres visibility — no dashboard light is fitted for them","correct":false}]'::jsonb);
insert into show_me_tell_me (id, category, topic, question, answer, is_show_me, choices) values (gen_random_uuid(), 'under_bonnet', 'Engine oil', 'Open the bonnet and tell me how you''d check that the engine has sufficient oil.', 'I''d pull the dipstick out, wipe it clean, put it back in fully, then pull it out again and check the level sits between the minimum and maximum marks.', false, '[{"text":"Read the dipstick the moment it is pulled out, unwiped, with the engine running","correct":false},{"text":"Pull the dipstick out, wipe it, refit it fully, then check the level between the marks","correct":true},{"text":"Look through the oil filler cap and check oil can be seen moving over the camshaft","correct":false},{"text":"Read the level off the dashboard oil pressure gauge with the engine idling","correct":false}]'::jsonb);
insert into show_me_tell_me (id, category, topic, question, answer, is_show_me, choices) values (gen_random_uuid(), 'under_bonnet', 'Coolant', 'Open the bonnet and tell me how you''d check that the engine has sufficient coolant.', 'I''d check the coolant level in the header tank sits between the minimum and maximum markers, and I''d only top it up when the engine is cold.', false, '[{"text":"Check the header tank level is between the two markers, topping up only when cold","correct":true},{"text":"Remove the radiator cap while the engine is warm and check it reaches the neck","correct":false},{"text":"Check the level in the washer bottle, which feeds the cooling system","correct":false},{"text":"Check the temperature gauge reads mid-way once the engine has warmed through","correct":false}]'::jsonb);
insert into show_me_tell_me (id, category, topic, question, answer, is_show_me, choices) values (gen_random_uuid(), 'under_bonnet', 'Brake fluid', 'Open the bonnet and tell me how you''d check that you have a safe level of hydraulic brake fluid.', 'I''d check the brake fluid reservoir and make sure the level sits between the minimum and maximum markings on the side of it.', false, '[{"text":"Check the brake fluid reservoir is filled right up to the top of its filler neck","correct":false},{"text":"Check the reservoir level sits between the minimum and maximum markings on its side","correct":true},{"text":"Press the brake pedal and check it does not sink, which shows the fluid is full","correct":false},{"text":"Check the fluid is clear rather than dark, the only level indicator fitted","correct":false}]'::jsonb);
insert into manoeuvres (id, name, steps, tips) values (gen_random_uuid(), 'Parallel park', '[{"title":"Choose your space","detail":"Find a gap roughly two car lengths long, indicate, and pull up alongside the car in front of the gap, about a car''s width away from it."},{"title":"Get into position","detail":"Line up so your rear bumper is roughly level with the other car''s rear bumper, select reverse, and check all around before moving."},{"title":"Begin reversing","detail":"Reverse slowly, steering fully towards the kerb once the car reaches roughly a 45-degree angle to it."},{"title":"Straighten up","detail":"As the car starts to come parallel to the kerb, steer smoothly the other way to bring the wheels straight."},{"title":"Final adjustment","detail":"Continue reversing slowly until the car is close to and parallel with the kerb, then stop."},{"title":"Check your position","detail":"Check you''re within about a car''s width of the kerb and not blocking a driveway, then apply the handbrake."}]'::jsonb, '{"Use reference points on your own car rather than fixed rules that apply to every road.","Keep the manoeuvre slow — speed makes it much harder to correct if you drift off line.","Pause for an all-round check at each stage rather than rushing through in one go."}');
insert into manoeuvres (id, name, steps, tips) values (gen_random_uuid(), 'Bay park (reverse)', '[{"title":"Select a bay","detail":"Drive past the bay you plan to use, positioning the car roughly two bays away and parallel to the row."},{"title":"Prepare to reverse","detail":"Check all around, select reverse gear, and begin reversing slowly while checking mirrors and blind spots."},{"title":"Turn towards the bay","detail":"As the bay lines appear in your mirrors, steer towards the bay while continuing to check around the car."},{"title":"Straighten into the bay","detail":"Straighten the steering as the car lines up centrally between the bay markings."},{"title":"Reverse in fully","detail":"Continue reversing slowly until the car is parked centrally and fully within the bay lines."},{"title":"Secure the car","detail":"Apply the handbrake, select neutral or park, and check the car hasn''t crossed any of the bay lines."}]'::jsonb, '{"Move at a very slow, controlled speed throughout the manoeuvre.","Keep up continuous all-round observation, not just mirror checks.","If you drift off line, pull forward and start the turn again rather than forcing it."}');
insert into manoeuvres (id, name, steps, tips) values (gen_random_uuid(), 'Forward bay park', '[{"title":"Approach the bay","detail":"Drive slowly through the car park and identify an empty bay ahead of you."},{"title":"Signal and position","detail":"Indicate if appropriate and position the car so you have enough room to turn into the bay."},{"title":"Turn in","detail":"Steer into the bay, checking mirrors and blind spots for pedestrians and other vehicles."},{"title":"Straighten up","detail":"Straighten the steering as the car lines up centrally within the bay markings."},{"title":"Drive in fully","detail":"Move forward until the car is parked centrally and square within the bay."},{"title":"Secure the car","detail":"Apply the handbrake and select neutral or park, checking the car is within the lines."}]'::jsonb, '{"Take it slowly — pedestrians can step out suddenly between parked cars.","Check the bay is wide enough and not reserved before you begin.","Use the bay lines and your car''s door pillars as reference points to stay central."}');
insert into manoeuvres (id, name, steps, tips) values (gen_random_uuid(), 'Pull up on the right', '[{"title":"Signal your intention","detail":"Check your mirrors and signal right in good time before pulling over."},{"title":"Position the car","detail":"Move over to a safe position close to the offside kerb, keeping clear of junctions and obstructions."},{"title":"Check before stopping","detail":"Check mirrors and blind spot again for traffic coming up behind or towards you before you stop."},{"title":"Stop safely","detail":"Bring the car to a stop parallel and close to the kerb, then apply the handbrake and select neutral."},{"title":"Prepare to move off","detail":"Signal right, then check mirrors and blind spot for oncoming and approaching traffic before moving away."},{"title":"Rejoin the road","detail":"Move off smoothly when it''s safe, crossing back to the correct side of the road promptly."}]'::jsonb, '{"Only use this manoeuvre where it''s legal and safe — never near a bend, junction or brow of a hill.","The blind-spot check matters more here since you''re pulling out into oncoming traffic.","Cancel your signal once you''ve safely moved off."}');
